function validAuctionMaps(list){var result=[];for(var i=0;i<list.length;i++)if(auctionValidMaps[list[i][0]])result.push(list[i]);return result;}
townmaps=validAuctionMaps(townmaps);monstermaps=validAuctionMaps(monstermaps);bossmaps=validAuctionMaps(bossmaps);
function sortAuctionMapsByLevel(list){
    var ordered=[];
    for(var i=0;i<list.length;i++){
        var match=/^#r(\d+)/.exec(list[i][2]);
        ordered.push({entry:list[i],level:match?parseInt(match[1],10):2147483647,index:i});
    }
    ordered.sort(function(a,b){return a.level-b.level||a.index-b.index;});
    for(var j=0;j<ordered.length;j++)list[j]=ordered[j].entry;
    return list;
}
townmaps=sortAuctionMapsByLevel(townmaps);monstermaps=sortAuctionMapsByLevel(monstermaps);bossmaps=sortAuctionMapsByLevel(bossmaps);
